'use strict';
const menu=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
if(menu&&navigation){menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));navigation.classList.toggle('open',!expanded);});navigation.addEventListener('click',event=>{if(event.target.closest('a')){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&navigation.classList.contains('open')){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');menu.focus();}});}
const filterButtons=[...document.querySelectorAll('[data-filter]')],projectCards=[...document.querySelectorAll('[data-category]')];
for(const button of filterButtons)button.addEventListener('click',()=>{const category=button.dataset.filter;for(const b of filterButtons)b.setAttribute('aria-pressed',String(b===button));let count=0;for(const card of projectCards){card.hidden=category!=='all'&&card.dataset.category!==category;if(!card.hidden)count++;}const status=document.querySelector('#filter-status');if(status)status.textContent=`Showing ${count} ${count===1?'project':'projects'}${category==='all'?' across all interests':'.'}`;});
const notes={
 jasper:{category:'PERSONAL AI / EXPLORATION',title:'Jasper.',status:'IN DEVELOPMENT',paragraphs:['Jasper is my personal assistant project: a place to explore how AI and automation could become useful in everyday life.','The aim is a calm, practical assistant that helps with planning, organising information and carefully chosen everyday tasks.'],heading:'The questions behind it',detail:'How can an assistant be useful, understandable and under its owner’s control? Organisation, context and carefully scoped automation are part of that exploration.',href:'https://github.com/Taccountant2026',link:'Explore my GitHub'},
 rover:{category:'ROBOTICS / CONCEPT STUDY',title:'A small rover. Big questions.',status:'CONCEPT & LEARNING',paragraphs:['This is a modular robotics idea, beginning with a four-wheel platform, motor control and sensors.','The longer-term direction brings together a Raspberry Pi, camera-based perception and autonomy. Each step starts with understanding the hardware, testing the controls and learning from the results.'],heading:'A practical learning path',detail:'The appeal is in bringing software and physical systems together, one understandable part at a time.',href:'#learning',link:'More about my learning'},
 web:{category:'WEB / PRACTICAL SYSTEMS',title:'Useful things for the web.',status:'ONGOING WORK',paragraphs:['My business websites are a practical place to explore clear information, useful tools and the steps that help someone move forward.','Bytova, RetroReplay UK and Stone & Sprig each have their own purpose. This personal website brings my interests together while giving each business its own space.'],heading:'Made for a real next step',detail:'A website should make it easier to understand an offer, find the right information and choose where to go next.',href:'#ventures',link:'Explore the businesses'},
 nature:{category:'NATURE / HANDS-ON CURIOSITY',title:'Rooted in the real world.',status:'PERSONAL INTEREST',paragraphs:['Nature, animals and the outdoors are an important part of what interests me beyond technology.','Gardens and growing offer their own kind of problem solving: observing, learning what works and making small improvements over time.'],heading:'A little room to grow',detail:'Stone & Sprig is where the garden side of that curiosity has a home, with practical ideas, planning tools and individual project enquiries.',href:'https://stoneandsprig.co.uk/',link:'Explore Stone & Sprig'}
};
const dialog=document.querySelector('#project-dialog');let returnFocus=null;
if(dialog){for(const button of document.querySelectorAll('[data-project]'))button.addEventListener('click',()=>{const note=notes[button.dataset.project];if(!note)return;returnFocus=button;document.querySelector('#dialog-category').textContent=note.category;document.querySelector('#dialog-title').textContent=note.title;document.querySelector('#dialog-status').textContent=note.status;const copy=document.querySelector('#dialog-copy');copy.replaceChildren();for(const text of note.paragraphs){const p=document.createElement('p');p.textContent=text;copy.append(p);}const h=document.createElement('h3');h.textContent=note.heading;const p=document.createElement('p');p.textContent=note.detail;copy.append(h,p);const link=document.querySelector('#dialog-link');link.href=note.href;link.textContent=note.link+' ↗';dialog.showModal();});dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});dialog.querySelector('#dialog-link').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>returnFocus?.focus());}
const routes={professional:{description:'Explore my projects and repositories on GitHub.',href:'https://github.com/Taccountant2026',label:'View my GitHub',destination:'github.com/Taccountant2026'},bytova:{description:'Head to Bytova for computer support, repair or small-business website enquiries.',href:'https://bytova.co.uk/',label:'Visit Bytova',destination:'bytova.co.uk'},rruk:{description:'Find the RRUK shop, product information and order-support routes.',href:'https://retroreplay.uk/contact',label:'Contact RetroReplay UK',destination:'retroreplay.uk/contact'},garden:{description:'Discuss your idea, space and timing through the Stone & Sprig project enquiry route.',href:'https://stoneandsprig.co.uk/project-brief.html',label:'Start a garden project enquiry',destination:'stoneandsprig.co.uk/project-brief.html'}};
const topic=document.querySelector('#contact-topic');if(topic)topic.addEventListener('change',()=>{const route=routes[topic.value];if(!route)return;document.querySelector('#contact-description').textContent=route.description;const link=document.querySelector('#contact-link');link.href=route.href;link.replaceChildren(document.createTextNode(route.label+' '));const arrow=document.createElement('span');arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';link.append(arrow);document.querySelector('#contact-destination').textContent=route.destination;});
const year=document.querySelector('#year');if(year)year.textContent=String(new Date().getFullYear());
const copyButton=document.querySelector('#copy-link');if(copyButton)copyButton.addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('https://leightonhepworth.com/');copyButton.textContent='Website link copied';if(status)status.textContent='Website address copied to your clipboard.';}catch{copyButton.textContent='leightonhepworth.com';if(status)status.textContent='The website address is leightonhepworth.com.';}});
